-- Template dynasties (TPL-DYNASTY-1021-CG, owner 2026-10-21). A dynasty is one email
-- strategy on ONE pipe (feature_slug x leg_key), cross-org; its versions are existing
-- prompts rows in order, the head = the highest position. See src/lib/template-dynasties.ts.
CREATE TABLE IF NOT EXISTS "template_dynasties" (
  "slug" text PRIMARY KEY NOT NULL,
  "name" text NOT NULL,
  "description" text NOT NULL,
  "signature" text NOT NULL,
  "identity" text NOT NULL,
  "feature_slug" text NOT NULL,
  "leg_key" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "template_dynasties_identity_check" CHECK ("identity" IN ('blind', 'named'))
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "idx_template_dynasties_description" ON "template_dynasties" ("description");
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "idx_template_dynasties_pipe_name" ON "template_dynasties" ("feature_slug", "leg_key", "name");
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "idx_template_dynasties_pipe_signature" ON "template_dynasties" ("feature_slug", "leg_key", "signature");
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "template_dynasty_versions" (
  "dynasty_slug" text NOT NULL REFERENCES "template_dynasties"("slug"),
  "prompt_type" text NOT NULL REFERENCES "prompts"("type"),
  "position" integer NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "template_dynasty_versions_pk" PRIMARY KEY ("dynasty_slug", "prompt_type")
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "idx_template_dynasty_versions_position" ON "template_dynasty_versions" ("dynasty_slug", "position");
--> statement-breakpoint
-- Seed: the 26 dynasties the owner validated on 2026-10-21.
INSERT INTO "template_dynasties" ("slug", "name", "description", "signature", "identity", "feature_slug", "leg_key") VALUES
  ('cold-click-website-click-named', 'Website Click', 'Gets a website visit by sending the prospect straight to your website, right after one sharp line about their problem.', 'Names the client. A sharp problem line, then the brand and its website URL as the ONLY call to action in every email. Aims for a click, never a reply or a call.', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-reply-free-offer-named', 'Named Free Offer', 'Gets a reply by offering the prospect something free from your list, made just for them, with your brand named.', 'Names the client. Offers something free from the client (its ''we give for free'' list, else a made-for-them deliverable, audit or benchmark) and closes on a one-word yes/no or ''relevant for you?''.', 'named', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-reply-intro-offer-blind', 'Blind Intro Offer', 'Gets a reply by offering the prospect an intro to your team, backed by one real result, while keeping your brand private.', 'Never names the client. The writer represents a team that has helped businesses like the prospect''s, backs it with one real proof point, and asks if they want an intro. No deliverable promised.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-reply-observation-named', 'Researched Observation', 'Gets a reply by asking one smart question about the prospect''s challenge, showing you studied their business, with your brand named.', 'Names the client in one plain sentence. Connects the prospect''s real signals into a hypothesis about their tension and closes on a diagnostic question that tests it. Never a meeting ask, never an offer.', 'named', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-click-page-click-named', 'Page Click', 'Gets a website visit by pointing the prospect to one page of yours and saying exactly what they will find there.', 'Names the client. Observation, implied problem, then one sentence on exactly what the client''s page shows, with the link as the only ask.', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-click-recommendation-stack-named', 'Recommendation Stack', 'Gets a website visit by recommending your brand in short punchy lines: their pain, your name, your proof, your link.', 'Names the client. No greeting, a vertical stack of one-line beats: prospect''s pain, client name, a real de-risker, the bare URL, real urgency. Reply or click.', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-click-brand-first-stack-named', 'Brand-First Stack', 'Gets a website visit by stacking your proof and your link in short punchy lines, opening on your brand name.', 'Names the client in the FIRST line. Recommendation Stack without the pain opener: client name and what it does, de-risker, bare URL, urgency.', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-reply-three-line-reply-named', 'Three-Line Reply', 'Gets a reply by inviting a quick reply after presenting your brand in three lines, best proof first.', 'Names the client. Exactly three lines: what the client does, why it matters to this prospect (best proof first), a one-line reply ask.', 'named', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-reply-free-offer-blind', 'Blind Free Offer', 'Gets a reply by offering the prospect something free from your list, like an audit or a benchmark, while keeping your brand private.', 'Never names the client. Research-backed pitch that offers the client''s free gift (from its ''we give for free'' list, else an audit or benchmark) and closes on a soft ''relevant for you?''.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-reply-pain-question-blind', 'Pain Question', 'Gets a reply by asking the prospect if they face the problem you solve, while keeping your brand private.', 'Never names the client, pitches nothing. Opens on one sharp pain and asks only whether they are dealing with it.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-click-three-line-click-named', 'Three-Line Click', 'Gets a website visit by inviting a click on your link after presenting your brand in three lines, best proof first.', 'Names the client. Same three lines as Three-Line Reply, but the only ask is a click on the client''s link.', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-reply-contrarian-opener-named', 'Contrarian Opener', 'Gets a reply by grabbing attention with a bold truth about the prospect''s market and asking for their thoughts, with your brand named.', 'Names the client. Opens on a bold, non-obvious truth about the prospect''s world, frames the problem, ends on a soft ''Thoughts?''. No offer, no link ask.', 'named', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-reply-website-click-named', 'Website Click', 'Gets a reply by sending the prospect straight to your website, right after one sharp line about their problem.', 'Names the client. A sharp problem line, then the brand and its website URL as the ONLY call to action in every email. Aims for a click, never a reply or a call.', 'named', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-click-brand-first-link-named', 'Brand-First Link', 'Gets a website visit by sending the prospect to your website, opening on what your brand does for them.', 'Names the client in the first line, no greeting, no problem opener. What the brand does for the reader, then the URL as the only ask (a click).', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-reply-one-line-free-offer-blind', 'One-Line Free Offer', 'Gets a reply by offering a free audit or insight in one single sentence, while keeping your brand private.', 'Never names the client. Greeting plus ONE sentence offering a free audit, benchmark or insight, then a tiny ''want me to send it?''.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('feedback-reply-feedback-gift-blind', 'Blind Feedback Gift', 'Gets a reply by offering your gift in exchange for quick feedback, keeping your brand private until the prospect replies.', 'Never names the client until the prospect replies. Offers a gift-for-feedback trade on behalf of an unnamed team.', 'blind', 'feedback-request-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-reply-client-rep-pitch-blind', 'Client Rep Pitch', 'Gets a reply by presenting your results, proof and guarantees with a free first step, while keeping your brand private.', 'Never names the client. Says up front it represents an unnamed client, stacks value levers (dream outcome, proof, risk reversal), closes on a zero-cost next step.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('feedback-reply-feedback-gift-named', 'Named Feedback Gift', 'Gets a reply by offering your gift and its value in exchange for quick feedback, with your brand named.', 'Names the client. Observation about the prospect, then the client''s gift with its stated worth in exchange for small feedback, closes on a reaction question.', 'named', 'feedback-request-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-reply-volume-questions-blind', 'Volume Questions', 'Gets a reply by asking two quick questions about the prospect''s prices and how they win customers today, while keeping your brand private.', 'Never names the client. Two one-line questions: what they would charge for a hypothetical volume of customers, and how they catch demand today.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('feedback-reply-diagnosis-gift-named', 'Diagnosis Gift', 'Gets a reply by offering your gift in exchange for quick feedback, after naming a challenge the prospect likely faces.', 'Names the client. Hypothesis about the prospect''s tension first, then the client''s gift, the feedback asked in return, and a diagnostic yes/no.', 'named', 'feedback-request-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-click-contrarian-opener-blind', 'Blind Contrarian', 'Gets a website visit by grabbing attention with a bold truth about the prospect''s market and asking for their thoughts, while keeping your brand private.', 'Never names the client. Same bold-truth opener and soft ''Thoughts?'' as Contrarian Opener.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-reply-give-first-insight-blind', 'Give-First Insight', 'Gets a reply by giving the prospect a useful insight in every email, while keeping your brand private.', 'Never names the client. Every email GIVES a useful insight grounded in what the client offers, no pain poking, no ask: the reply is left to the prospect.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-click-contrarian-opener-named', 'Contrarian Opener', 'Gets a website visit by grabbing attention with a bold truth about the prospect''s market and asking for their thoughts, with your brand named.', 'Names the client. Opens on a bold, non-obvious truth about the prospect''s world, frames the problem, ends on a soft ''Thoughts?''. No offer, no link ask.', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-reply-intro-offer-named', 'Named Intro Offer', 'Gets a reply by offering the prospect an intro to your team, backed by one real result, with your brand named.', 'Names the client and its URL. Same intro offer as Blind Intro Offer: one real proof point, then ''want an intro?''. No deliverable promised.', 'named', 'sales-cold-email-outreach', 'lead_found_to_conversation'),
  ('cold-click-intro-offer-named', 'Named Intro Offer', 'Gets a website visit by offering the prospect an intro to your team, backed by one real result, with your brand named.', 'Names the client and its URL. Same intro offer as Blind Intro Offer: one real proof point, then ''want an intro?''. No deliverable promised.', 'named', 'sales-cold-email-outreach', 'lead_found_to_website_visit'),
  ('cold-click-intro-offer-blind', 'Blind Intro Offer', 'Gets a website visit by offering the prospect an intro to your team, backed by one real result, while keeping your brand private.', 'Never names the client. The writer represents a team that has helped businesses like the prospect''s, backs it with one real proof point, and asks if they want an intro. No deliverable promised.', 'blind', 'sales-cold-email-outreach', 'lead_found_to_website_visit')
ON CONFLICT ("slug") DO NOTHING;
